class N:
    def __init__(s,d=8,fr=1.0): s.d=d; s.fr=fr
    def fit(s,X,y,seed=0):
        s.r=np.random.default_rng(seed); s.t=s.build(X,y,0); return s
    def build(s,X,y,dep):
        if dep>=s.d or len(y)<4: return y.mean()
        cols=s.r.choice(X.shape[1],max(1,int(X.shape[1]*s.fr)),replace=False)
        best=None
        for j in cols:
            for t in np.unique(X[:,j])[:-1]:
                m=X[:,j]<=t; sl=[y[m],y[~m]]
                g=sum(((v-v.mean())**2).sum() for v in sl)
                if best is None or g<best[0]: best=(g,j,t)
        _,j,t=best; m=X[:,j]<=t
        return (j,t,s.build(X[m],y[m],dep+1),s.build(X[~m],y[~m],dep+1))
    def pred(s,x):
        while isinstance(s.t,tuple):
            j,t,l,r=s.t; s.t=l if x[j]<=t else r
        return s.t
